    agregar("G38-L3-12", CLASE_38, "L3", "Termometría de radiador auxiliar de aceite de transmisión CVT: delta de temperatura entre entrada y salida de apenas 2°C (temperatura de entrada 112°C y salida 110°C) comprobándose obstrucción parcial del serpentín por lodo metálico de desgaste que impide disipar el calor generado por el variador en régimen de carretera.", "TALLER", "termometria_radiador_auxiliar_delta_2c", "delta_temperatura_radiador_2c|obstruccion_serpentin_lodo|aceite_cvt_a_112c", "falla_radiador_motor", "", "NO", "NO", "", "L3 serpentín obstruido genera delta térmico nulo de 2°C y recalentamiento.")
    agregar("G38-L3-13", CLASE_38, "L3", "DTC P0776 (Pressure Control Solenoid 'B' Performance/Stuck Off) en transmisión automática variable: la electroválvula proporcional no modula la contrapresión de la polea secundaria provocando deslizamiento brusco de la cadena de eslabones basculantes que genera limalla visible en el imán de cárter.", "TECNICO", "diagnostico_dtc_p0776_solenoide_b", "dtc_p0776|solenoide_b_stuck_off|deslizamiento_cadena_variador|limalla_carter", "falla_caja_cambios", "P0776", "NO", "NO", "", "L3 código P0776 por solenoide secundario trabado con generación de limalla.")
    agregar("G38-L3-14", CLASE_38, "L3", "Incompatibilidad de adaptación de embragues tras sustitución de mecatrónica en caja DSG: el procedimiento de ajuste básico canal 060 con herramienta VCDS aborta repetidamente en el paso 255 por falta de presión hidráulica mínima (requiere 45 bar continuos y la bomba entrega 32 bar por desgaste interno de engranajes).", "TALLER", "ajuste_basico_canal_060_aborta", "ajuste_basico_vcds_aborta_paso_255|presion_32bar_insuficiente_vs_45bar", "falla_programacion", "", "NO", "NO", "", "L3 ajuste básico VCDS aborta por déficit de presión hidráulica a 32 bar.")
    agregar("G38-L3-15", CLASE_38, "L3", "Registro de parámetros de transmisión CVT bajo prueba de dinamómetro: con acelerador al 80% las poleas del variador presentan un tiempo de transición de relación corta a relación larga de 3.8 segundos (especificación menor a 1.2 s) acompañado de pico térmico en el líquido de 115°C debido a fugas en los retenes de teflón del pistón de la polea motriz.", "TECNICO", "dinamometro_transicion_variador_3_8s", "transicion_variador_3_8s_vs_1_2s|pico_termico_115c|fuga_retenes_teflon_polea", "falla_motor", "", "NO", "NO", "", "L3 retardo de 3.8s en transición de poleas por fuga en sellos de teflón.")

