    agregar("G39-L2-01", CLASE_39, "L2", "En un Fiat Palio con caja Dualogic el cambio cae a Neutral de golpe al detenerse en esquinas; la electrobomba hidráulica del robot no arranca al abrir la puerta del chofer.", "COTIDIANO", "detencion_esquinas", "salto_a_neutro_dualogic|electrobomba_no_arranca_puerta", "falla_caja_automatica", "", "NO", "SI", "Sobrecalentamiento o solenoides en caja automatica CVT / DSG", "L2 caída a Neutral por electrobomba inactiva en Dualogic.")
    agregar("G39-L2-02", CLASE_39, "L2", "Volkswagen Gol I-Motion con DTC P0840 referente a sensor de presión hidráulica del grupo robotizado; la presión se desploma de 45 bar a 22 bar en un solo cambio.", "TECNICO", "diagnostico_i_motion", "dtc_p0840|presion_desploma_45_a_22bar|grupo_robotizado_imotion", "falla_dsg", "P0840", "NO", "SI", "Sobrecalentamiento o solenoides en caja automatica CVT / DSG", "L2 despresurización de acumulador en VW I-Motion vs DSG.")
    agregar("G39-L2-03", CLASE_39, "L2", "Fuga visible de aceite hidráulico verde específico (Tutela CS Speed) por el retén del pistón de acople del embrague del robot Dualogic; nivel en reservorio vacío.", "TALLER", "inspeccion_robot_dualogic", "fuga_tutela_cs_speed|reten_piston_embrague_robot|deposito_vacio", "fuga_aceite_caja", "", "NO", "SI", "Falta o degradacion de aceite de caja de cambios", "L2 fuga de fluido hidráulico específico del robot vs valvulina.")
    agregar("G39-L2-04", CLASE_39, "L2", "Hola maestro, tengo un Fiat Punto Dualogic. Al acelerar en primera da un zapateo terrible y salta aviso 'Hacer controlar cambio'; me dijeron que el robot está descalibrado.", "WHATSAPP", "salida_primera_dualogic", "zapateo_salida_primera|aviso_hacer_controlar_cambio|descalibrado", "disco_patina", "", "NO", "SI", "Disco de embrague desgastado o patinando", "L2 descalibración de embrague en Dualogic vs disco patinando.")
    agregar("G39-L2-05", CLASE_39, "L2", "Acumulador de presión esférico del sistema robotizado desinflado (membrana de nitrógeno rota); la bomba eléctrica arranca cada vez que se realiza un cambio de marcha.", "TECNICO", "prueba_ciclado_electrobomba", "acumulador_esferico_desinflado|bomba_arranca_cada_cambio", "falla_bomba_embrague", "", "NO", "SI", "Falla en bombin o bomba hidraulica de embrague", "L2 membrana de nitrógeno rota cicla bomba en cada cambio.")
    agregar("G39-L2-06", CLASE_39, "L2", "En Chevrolet Corsa Easytronic el motor no arranca y en el tablero parpadea una letra 'F'; el actuador electromecánico de embrague tiene los carbones gastados.", "TALLER", "diagnostico_easytronic_letra_f", "letra_f_parpadea_easytronic|motor_no_arranca|carbones_actuador_gastados", "falla_motor_arranque", "", "NO", "NO", "", "L2 fallo 'F' clásico en Easytronic por carbones de actuador.")
    agregar("G39-L2-07", CLASE_39, "L2", "DTC P0914 referente a circuito de posición del cambio de marchas en caja robotizada; el potenciómetro de selección de pasillo tiene pistas de carbón gastadas.", "TECNICO", "diagnostico_p0914", "dtc_p0914|potenciometro_seleccion_pistas_gastadas|bloqueo_robot", "falla_selectora_mecanica", "P0914", "NO", "NO", "", "L2 código P0914 de sensor de posición de robot.")
    agregar("G39-L2-08", CLASE_39, "L2", "Mi carro Fiat con caja robotisada pitó una chicharra en marcha y se quedo en neutro sin poder meter cambios en medio de la pista.", "ERROR_ORTOGRAFICO", "bloqueo_en_marcha", "chicharra_alarma|quedo_en_neutro_sin_cambios|caja_robotizada", "falla_caja_automatica", "", "NO", "SI", "Sobrecalentamiento o solenoides en caja automatica CVT / DSG", "L2 alarma y caída a Neutro con ortografía informal.")
    agregar("G39-L2-09", CLASE_39, "L2", "Buenas, el carro arranca bien en frío pero cuando calienta el motor en tráfico la caja I-Motion no engrana la reversa ni la primera velocidad.", "WHATSAPP", "temperatura_trafico_imotion", "imotion_falla_en_caliente|no_engrana_reversa_ni_primera", "falla_embrague", "", "NO", "SI", "Disco de embrague desgastado o patinando", "L2 falla térmica en actuador robotizado I-Motion.")
    agregar("G39-L2-10", CLASE_39, "L2", "Relé de potencia de la electrobomba de la caja robotizada con contactos quemados; la bomba no recibe corriente de 12V y el sistema no levanta presión.", "TALLER", "inspeccion_rele_electrobomba", "rele_electrobomba_quemado|sin_12v_bomba|sin_presion_robot", "falla_fusible", "", "NO", "NO", "", "L2 relé quemado anula accionamiento de bomba.")
    agregar("G39-L2-11", CLASE_39, "L2", "DTC P1818 en sistema Dualogic por falla de control de embrague; el vástago del cilindro de empuje no alcanza la posición de reposo calibrada.", "TECNICO", "diagnostico_dtc_p1818", "dtc_p1818|vastago_cilindro_no_alcanza_reposo|falla_control_embrague", "desgaste_embrague", "P1818", "NO", "SI", "Disco de embrague desgastado o patinando", "L2 código P1818 por desalineación de vástago de embrague.")
    agregar("G39-L2-12", CLASE_39, "L2", "Contaminación del fluido hidráulico del robot con agua por condensación; el líquido está turbio y las electroválvulas proporcionales se traban mecánicamente.", "TALLER", "fluido_tutela_contaminado", "fluido_robot_turbio_agua|electrovalvulas_trabadas", "falta_aceite_caja", "", "NO", "SI", "Falta o degradacion de aceite de caja de cambios", "L2 fluido del robot contaminado traba electroválvulas.")
    agregar("G39-L2-13", CLASE_39, "L2", "Al desacelerar para doblar en una esquina la transmisión robotizada mete rebaje violento de 3ra a 1ra directamente saltándose la segunda marcha.", "COTIDIANO", "rebaje_brusco_esquina", "rebaje_violento_3ra_a_1ra|se_salta_segunda_marcha", "falla_caja_sincronizadores", "", "NO", "NO", "", "L2 error de lógica de salto de pasillo en robot.")
    agregar("G39-L2-14", CLASE_39, "L2", "Procedimiento de calibración de fin de línea aborta repetidamente por temperatura de embrague calculada superior a 110°C en escáner multimarca.", "TECNICO", "calibracion_fin_de_linea_aborta", "calibracion_aborta_embrague_110c|sobrecalentamiento_robot", "falla_embrague", "", "NO", "SI", "Disco de embrague desgastado o patinando", "L2 calibración de robot abortada por cálculo térmico.")
    agregar("G39-L2-15", CLASE_39, "L2", "Palanca selectora electrónica en consola central no envía señal de cambio manual +/-; la placa de contactos resistivos tiene pistas sucias con sulfato.", "TALLER", "inspeccion_palanca_consola", "palanca_consola_no_envia_senal|contactos_sulfatados", "falla_palanca_varillas", "", "NO", "NO", "", "L2 placa de palanca selectora sulfatada.")

    # --- L3 (15 casos) ---
    agregar("G39-L3-01", CLASE_39, "L3", "En un Fiat Grand Siena 1.6 con transmisión robotizada Dualogic Plus se activa alarma sonora continua con mensaje en pantalla 'Hacer controlar cambio' al quedar en ralentí en semáforos, pasando la caja espontáneamente a Neutral (N). Con escáner se lee DTC P0845 (Transmission Fluid Pressure Sensor) y P1773 (Hydraulic Circuit Pressure Low). En línea de datos la presión hidráulica decae de 48 bar a 28 bar en apenas 6 segundos sin realizar cambios; al abrir la puerta del chofer la electrobomba arranca durante 18 segundos con sonido forzado. Se comprobó que el acumulador esférico de nitrógeno (pulmón de presión) perdió la precarga de 30 bar y tiene fuga por el diafragma.", "TECNICO", "diagnostico_dualogic_pulmon_desinflado", "dtc_p0845_p1773|presion_cae_48_a_28bar_en_6s|pulmon_nitrogeno_sin_precarga|salto_a_neutro", "falla_caja_automatica", "P0845", "NO", "SI", "Sobrecalentamiento o solenoides en caja automatica CVT / DSG", "L3 código P0845 y P1773 por pulmón de presión desinflado en Dualogic.")
    agregar("G39-L3-02", CLASE_39, "L3", "Volkswagen Fox 1.6 con caja robotizada I-Motion presenta trepidación violenta y tirones incontrolables al arrancar en primera velocidad tras 20 minutos de marcha. Con el escáner se evaluó el índice de degradación de embrague arrojando valor de 9200 unidades (límite de adaptación 6000 unidades) y la posición del vástago de embrague acusa oscilaciones de +/- 3.5 mm durante la fase de modulación. Se ejecutó el ajuste básico de adaptación del punto de contacto (Kiss Point) con software VCDS pero el procedimiento arroja 'Error 07' debido a que el retén del actuador de embrague rezuma fluido hidráulico contaminando el forro del disco.", "TALLER", "ajuste_basico_kiss_point_vcds_error07", "degradacion_embrague_9200_unidades|ajuste_kiss_point_error07|actuador_rezuma_fluido", "falla_disco_patina", "", "NO", "SI", "Disco de embrague desgastado o patinando", "L3 ajuste básico Kiss Point falla por contaminación de actuador en I-Motion.")
    agregar("G39-L3-03", CLASE_39, "L3", "Falla de encendido en Chevrolet Meriva con caja robotizada Easytronic: en el cuadro de instrumentos destella la letra 'F' y el motor de arranque no gira. Con escáner se diagnostica DTC P1607 (Clutch Actuator Position Control Error). Al desmontar el actuador electrohidráulico integrado en la caja se constató que los carbones del motor eléctrico de accionamiento del vástago de embrague se desgastaron por completo quedando en 3 mm, bloqueando el émbolo en posición intermedia y dejando la ECU de transmisión en estado de bloqueo por seguridad.", "TECNICO", "diagnostico_easytronic_p1607_carbones", "dtc_p1607_letra_f_easytronic|carbones_motor_embrague_3mm|bloqueo_arranque", "falla_motor_arranque", "P1607", "NO", "NO", "", "L3 código P1607 y letra F por carbones gastados en actuador Easytronic.")
    agregar("G39-L3-04", CLASE_39, "L3", "En un Fiat Palio Dualogic el vehículo arranca bien en frío pero al alcanzar 85°C el sistema se rehúsa a insertar la marcha atrás y la 5ta velocidad emitiendo 3 pitidos de alarma. Con escáner multimarca se lee DTC P0914 (Gear Shift Position Circuit); la medición de voltaje en el potenciómetro de selección de pasillo registra salto abrupto de 1.2V a 4.9V al llegar a la posición del pasillo de reversa debido a desgaste de la pista resistiva por vibración térmica del cuerpo del robot.", "TECNICO", "analisis_potenciometro_seleccion_p0914", "dtc_p0914|potenciometro_pasillo_salto_1_2_a_4_9v|no_entra_reversa_ni_quinta_85c", "falla_caja_sincronizadores", "P0914", "NO", "SI", "Falta o degradacion de aceite de caja de cambios", "L3 código P0914 por salto de voltaje en potenciómetro a 85°C.")
    agregar("G39-L3-05", CLASE_39, "L3", "Hola maestro, tengo un Fiat Linea Dualogic. En el tráfico cuando me paro en una luz roja el carro se pone solo en neutro y empieza a pitar el tablero con aviso de 'Hacer controlar cambio'. Para que vuelva a andar tengo que apagar el carro, abrir y cerrar la puerta del chofer para que suene el motorcito de la caja y recién me deja poner primera.", "WHATSAPP", "diagnostico_linea_dualogic_semaforo", "salto_a_neutro_en_roja|aviso_controlar_cambio|apagar_abrir_puerta_reactiva", "falla_caja_automatica", "", "NO", "SI", "Sobrecalentamiento o solenoides en caja automatica CVT / DSG", "L3 relato WhatsApp de ciclo de puerta para reactivar bomba Dualogic.")
    agregar("G39-L3-06", CLASE_39, "L3", "Inspección de grupo electrohidráulico Dualogic: el depósito de aceite específico Tutela CS Speed de 0.7 litros se encuentra con nivel en cero; el fluido se derramó en su totalidad a través del retén del sensor de posición de inserción hacia el interior de la campana de la caja, provocando que la electrobomba trabaje en vacío a más de 8000 rpm hasta quemar el bobinado con DTC P0942 (Hydraulic Pressure Unit).", "TALLER", "desarme_robot_tutela_cero_p0942", "dtc_p0942|nivel_tutela_cero|electrobomba_quemada_en_vacio|fuga_reten_posicion", "falta_aceite_caja", "P0942", "NO", "SI", "Falta o degradacion de aceite de caja de cambios", "L3 código P0942 por bomba quemada en seco tras fuga de Tutela CS Speed.")
    agregar("G39-L3-07", CLASE_39, "L3", "DTC P1773 en Volkswagen Voyage I-Motion; la electrobomba hidráulica del grupo de cambio tarda 32 segundos en presurizar el acumulador desde 35 bar hasta 50 bar (especificación OEM menor a 8 segundos). Al desarmar la bomba de engranajes acoplada al motor eléctrico se verificó desgaste por cavitación en los piñones internos de bombeo provocado por uso de líquido de frenos común en lugar de aceite sintético hidráulico ISO VG 32.", "TECNICO", "tiempo_presurizacion_32s_vs_8s", "dtc_p1773|presurizacion_tarda_32s_vs_8s|desgaste_cavitacion_pinones_bomba", "falla_liquido_frenos", "P1773", "NO", "SI", "Falla en bombin o bomba hidraulica de embrague", "L3 presurización demora 32s vs 8s por cavitación con fluido incorrecto.")
    agregar("G39-L3-08", CLASE_39, "L3", "Mi carro Fiat Palio robotisado ase un sonido de pito agudo cuando boy a doblar y se queda en neutro botando un liquido verde claro aceitoso por debajo del parachoque del lado de la caja con codigo P0845.", "ERROR_ORTOGRAFICO", "fuga_liquido_verde_p0845", "pito_agudo|queda_en_neutro|gotea_liquido_verde_claro|dtc_p0845", "fuga_refrigerante", "P0845", "NO", "SI", "Falta o degradacion de aceite de caja de cambios", "L3 código P0845 con goteo verde Tutela con ortografía informal.")
    agregar("G39-L3-09", CLASE_39, "L3", "Falla en la electroválvula proporcional de modulación de embrague EV0 en caja Dualogic: la válvula presenta resistencia eléctrica de 2.8 ohms correcta pero al aplicarse modulación PWM de 800 mA el vástago se traba mecánicamente por acumulación de barniz ferroso, impidiendo la apertura suave y provocando que el auto se cale violentamente al detenerse.", "TECNICO", "inspeccion_electrovalvula_ev0_dualogic", "electrovalvula_ev0_trabada_barniz|auto_se_cala_al_frenar|resistencia_2_8ohm_ok", "falla_embrague_mecanico", "", "NO", "SI", "Disco de embrague desgastado o patinando", "L3 electroválvula EV0 trabada mecánicamente cala el motor al detenerse.")
    agregar("G39-L3-10", CLASE_39, "L3", "Buenas tardes, en mi VW Fox I-Motion los cambios pasan a los golpes como si soltara el embrague de golpe. Lo escanearon y salieron códigos P0840 y P0914. Me dijeron que el robot perdió el aprendizaje de las marchas y que el sensor de presión de la caja está marcando cualquier cosa por falso contacto en la ficha.", "WHATSAPP", "diagnostico_fox_imotion_golpes", "cambios_a_los_golpes|dtc_p0840_p0914|perdida_aprendizaje_marchas|falso_contacto_ficha", "falla_caja_sincronizadores", "P0840", "NO", "SI", "Falta o degradacion de aceite de caja de cambios", "L3 códigos P0840 y P0914 por pérdida de aprendizaje en I-Motion.")
    agregar("G39-L3-11", CLASE_39, "L3", "Análisis con osciloscopio automotriz de la señal del sensor de posición del actuador de embrague: la señal analógica entrega saltos de ruido de 1.5 Vpp superpuestos a la rampa de desplazamiento debido a rotura del blindaje del cableado en el paso de rueda delantero izquierdo, provocando tirones espasmódicos del motor paso a paso.", "TECNICO", "oscilograma_ruido_1_5vpp_posicion", "ruido_1_5vpp_senal_posicion_embrague|blindaje_roto_paso_rueda|tirones_espamodicos", "falla_sensor_ckp", "", "NO", "NO", "", "L3 ruido electromagnético de 1.5 Vpp desestabiliza actuador de embrague.")
    agregar("G39-L3-12", CLASE_39, "L3", "El cliente reclama que el vehículo no permite seleccionar ninguna marcha permaneciendo el indicador de tablero en 'N' parpadeante. Se comprobó que el interruptor de freno de doble circuito montado en la pedalera tiene el contacto secundario abierto (línea de datos del robot no recibe confirmación de freno pisado), bloqueando la orden de inserción de 1ra por enclavamiento de seguridad.", "TALLER", "diagnostico_interruptor_freno_doble_circuito", "n_parpadea_bloqueada|interruptor_freno_contacto_abierto|sin_confirmacion_pedal", "falla_interruptor_stop", "", "NO", "NO", "", "L3 interlock de seguridad: interruptor de pedalier bloquea robot en N.")
    agregar("G39-L3-13", CLASE_39, "L3", "Medición de consumo eléctrico de la electrobomba de grupo robotizado: al activar con escáner el motor consume 28 amperios en arranque y se mantiene en 22 amperios sostenidos (especificación 10 a 14 A) debido a desgaste de cojinetes del inducido eléctrico que provocan sobrecalentamiento del fusible de 30A y disparo térmico.", "TECNICO", "amperaje_electrobomba_22a_vs_12a", "consumo_bomba_22a_vs_12a|cojinetes_inducido_gastados|sobrecalentamiento_fusible_30a", "falla_alternador", "", "NO", "NO", "", "L3 consumo excesivo de 22 A en bomba del robot por cojinetes dañados.")
    agregar("G39-L3-14", CLASE_39, "L3", "Desgaste del pasador mecánico de acoplamiento entre el pistón hidráulico del robot y la horquilla de desembrague de la caja manual: holgura de 4.2 mm en el perno esférico genera un juego muerto que la TCM interpreta como desgaste excesivo del disco, limitando la salida y activando mensaje de advertencia en tablero.", "TALLER", "holgura_perno_esferico_4_2mm", "holgura_perno_esferico_4_2mm|juego_muerto_horquilla|tcm_limita_salida", "falla_collarin", "", "NO", "SI", "Desgaste en collarin de empuje o crapodina de embrague", "L3 juego de 4.2 mm en perno esférico del robot descalibra lectura.")
    agregar("G39-L3-15", CLASE_39, "L3", "Prueba de hermeticidad con nitrógeno a 50 bar en bloque hidráulico robotizado: caída de presión de 15 bar en 3 minutos a través de la válvula antirretorno interna de la bomba de alta presión, obligando a ciclar la bomba eléctrica cada 12 segundos y agotando la batería auxiliar de 12V.", "TECNICO", "prueba_estanqueidad_nitrogeno_50bar", "caida_15bar_en_3min_valvula_antirretorno|bomba_cicla_cada_12s|agota_bateria", "falla_bateria", "", "NO", "NO", "", "L3 caída de 15 bar en 3 min por válvula antirretorno cicla bomba a 12s.")

