    agregar("G40-L1-03", CLASE_40, "L1", "Con el pedal suelto no suena nada, pero apoyo el pie en el embrague y chilla.", "COTIDIANO", "apoyo_pie_embrague", "chilla_al_apoyar_pie_embrague", "", "", "SI", "NO", "", "L1 ruido al hacer contacto con diafragma.")
