    agregar("G40-L1-06", CLASE_40, "L1", "Siento una vibración pulsante en la planta del pie al apretar el embrague.", "COTIDIANO", "accionamiento", "vibracion_pulsante_pie_al_apretar", "", "", "SI", "NO", "", "L1 pulsación transmitida por pista picada.")
    agregar("G40-L1-07", CLASE_40, "L1", "El collarín de embrague chilla durísimo cuando meto primera para salir.", "TALLER", "primera_marcha", "collarin_chilla_al_meter_primera", "", "", "SI", "NO", "", "L1 chillido en maniobra de salida.")
    agregar("G40-L1-08", CLASE_40, "L1", "Mi carro ase un rechinido como cama vieja cuando aprieto el pedal del cloch.", "ERROR_ORTOGRAFICO", "accionamiento", "rechinido_cama_vieja_al_apretar_cloch", "", "", "SI", "NO", "", "L1 rechinido al pisar con ortografía informal.")
