    # --- L2 (15 casos) ---
    agregar("G40-L2-01", CLASE_40, "L2", "Chillido agudo de rodamiento seco que aparece exactamente al presionar el pedal de embrague a fondo; al soltar el pedal en punto muerto el motor queda en silencio absoluto.", "COTIDIANO", "embrague_a_fondo_vs_suelto", "chillido_al_pisar_embrague|silencio_al_soltar", "rodaje_eje_primario", "", "NO", "SI", "Rodajes de transmision manual o eje primario gastados", "L2 ruido al pisar y silencio al soltar descarta eje primario.")
    agregar("G40-L2-02", CLASE_40, "L2", "Vibración áspera en el pie al pisar el embrague en ralentí; el cojinete de empuje mecánico tiene las bolas picadas y la pista de rodadura sin lubricación.", "TALLER", "ralenti_pedal_pisado", "vibracion_aspera_en_el_pie|cojinete_empuje_sin_lubricacion", "falla_plato_opresor", "", "NO", "SI", "Disco de embrague desgastado o patinando", "L2 aspereza en pedal por rodamiento de empuje seco.")
    agregar("G40-L2-03", CLASE_40, "L2", "Crapodina hidráulica (CSC) emite zumbido chirriante al desacoplar marchas y rezuma líquido DOT 4 por el orificio de ventilación inferior de la campana de embrague.", "TECNICO", "inspeccion_csc_fuga", "csc_zumbido_al_desacoplar|goteo_dot4_campana", "fuga_aceite_caja", "", "NO", "SI", "Falla en bombin o bomba hidraulica de embrague", "L2 crapodina hidráulica con ruido y fuga de fluido.")
    agregar("G40-L2-04", CLASE_40, "L2", "Hola maestro, con el carro parado en neutro no suena nada, pero apenas piso el embrague para meter cambio empieza un chiiii metálico que ensordece.", "WHATSAPP", "neutro_vs_pedal_pisado", "silencio_en_neutro|chiii_metalico_al_pisar", "rodajes_caja", "", "NO", "SI", "Rodajes de transmision manual o eje primario gastados", "L2 silencio en neutro y chillido al pisar descarta caja.")
    agregar("G40-L2-05", CLASE_40, "L2", "El collarín de empuje se quedó pegado y girando torcido, desgastando y cortando las puntas de los dedos del diafragma de la prensa de embrague.", "TECNICO", "desarme_embrague_dedos", "collarin_torcido|dedos_diafragma_cortados_friccion", "falla_prensa_embrague", "", "NO", "SI", "Disco de embrague desgastado o patinando", "L2 collarín atascado corta dedos del diafragma.")
    agregar("G40-L2-06", CLASE_40, "L2", "Chirrido estridente que aumenta su volumen conforme se pisa con mayor fuerza el pedal de embrague; no hay patinamiento del disco ni pérdida de tracción.", "COTIDIANO", "accionamiento_progresivo", "chirrido_aumenta_con_fuerza_pedal|sin_patinamiento_disco", "disco_desgastado", "", "NO", "SI", "Disco de embrague desgastado o patinando", "L2 chillido proporcional a carga sin patinamiento de disco.")
    agregar("G40-L2-07", CLASE_40, "L2", "Guía tubular del collarín de empuje rayada y con óxido; el cojinete se traba al deslizar provocando pedal duro y chirrido de fricción seca.", "TALLER", "inspeccion_guia_tubular", "guia_tubular_rayada_oxido|cojinete_se_traba|pedal_duro", "falla_bomba_embrague", "", "NO", "SI", "Falla en bombin o bomba hidraulica de embrague", "L2 guía tubular rayada traba deslizamiento del collarín.")
    agregar("G40-L2-08", CLASE_40, "L2", "Mi auto ase un grillo que chilla durisimo solo cuando meto el pie al cloch; si saco el pie se apaga el grillo al tiro.", "ERROR_ORTOGRAFICO", "accionamiento_pie", "grillo_solo_al_meter_pie_cloch|apaga_al_sacar_pie", "rodaje_primario", "", "NO", "SI", "Rodajes de transmision manual o eje primario gastados", "L2 grillo exclusivo al pisar con ortografía informal.")
    agregar("G40-L2-09", CLASE_40, "L2", "Buenas, el mecánico me dijo que la crapodina se recalentó porque anduve con el pie apoyado en el pedal del embrague en el tráfico de la ciudad.", "WHATSAPP", "habito_pie_apoyado", "crapodina_recalentada_pie_apoyado|ruido_al_pisar", "desgaste_pastillas", "", "NO", "NO", "", "L2 crapodina dañada por mal hábito de pie apoyado.")
    agregar("G40-L2-10", CLASE_40, "L2", "Rodamiento de desembrague con juego axial de 2.5 mm y jaula porta-bolas partida; al desmontar caen las bolas de acero sueltas dentro de la campana.", "TECNICO", "desarme_campana_bolas_sueltas", "juego_axial_2_5mm_collarin|jaula_partida_bolas_sueltas", "falla_caja_interna", "", "NO", "SI", "Rodajes de transmision manual o eje primario gastados", "L2 jaula de bolas partida en collarín de empuje.")
    agregar("G40-L2-11", CLASE_40, "L2", "Silbido agudo constante al pisar el embrague en semáforos; el disco de embrague y la prensa tienen solo 10,000 km pero no cambiaron el collarín viejo.", "COTIDIANO", "semaforo_pedal_a_fondo", "silbido_al_pisar_semaforo|embrague_nuevo_collarin_viejo", "embrague_patina", "", "NO", "SI", "Disco de embrague desgastado o patinando", "L2 collarín no reemplazado en kit previo emite silbido.")
    agregar("G40-L2-12", CLASE_40, "L2", "Horquilla de embrague con desgaste por rozamiento en los apoyos del collarín; el cojinete apoya cruzado provocando zumbido y dureza de pedal.", "TALLER", "inspeccion_horquilla_apoyos", "horquilla_desgastada_apoyos|collarin_apoya_cruzado|zumbido", "falla_bombin", "", "NO", "SI", "Falla en bombin o bomba hidraulica de embrague", "L2 horquilla desgastada cruza collarín.")
    agregar("G40-L2-13", CLASE_40, "L2", "Al pisar el pedal a medio recorrido suena un zumbido áspero que se agudiza al llegar al fondo; los cambios entran perfectamente sin rascar.", "COTIDIANO", "medio_recorrido_pedal", "zumbido_medio_recorrido_agudo_al_fondo|cambios_entran_bien", "falla_caja_cambios", "", "NO", "SI", "Falta o degradacion de aceite de caja de cambios", "L2 ruido progresivo con cambios suaves descarta sincronizadores.")
    agregar("G40-L2-14", CLASE_40, "L2", "Crapodina de empuje con pista de contacto cónica azulada por sobrecalentamiento por encima de 250°C; la grasa interna se carbonizó totalmente.", "TECNICO", "inspeccion_termica_crapodina", "pista_conica_azulada_250c|grasa_carbonizada_crapodina", "falla_disco_friccion", "", "NO", "SI", "Disco de embrague desgastado o patinando", "L2 grasa carbonizada a 250°C en crapodina.")
    agregar("G40-L2-15", CLASE_40, "L2", "Pulsación y traqueteo rítmico en el pedal de embrague al presionarlo; el rodamiento de empuje perdió tres bolas de un lado generando desequilibrio.", "TALLER", "prueba_tactil_pedalier", "pulsacion_ritmica_al_pisar|perdida_tres_bolas_collarin", "falla_volante_bimasa", "", "NO", "NO", "", "L2 pérdida de bolas genera pulsación en pedal.")

    # --- L3 (15 casos) ---
    agregar("G40-L3-01", CLASE_40, "L3", "Toyota Hilux 1GD con transmisión manual de 6 marchas ingresa por ruido estridente en la zona de la campana. En ralentí con vehículo detenido en punto muerto y pedal de embrague suelto el motor opera en silencio a 48 dBA. En el instante exacto en que el conductor apoya el pie en el pedal con 50 N de carga el nivel sonoro se dispara a 82 dBA con un chillido metálico agudo de 3.4 kHz característico de rodamiento seco; al pisar el pedal a fondo el ruido se intensifica y transmite vibración de alta frecuencia a la suela del zapato. Al soltar nuevamente el pedal a neutro el ruido desaparece de inmediato descartando rodamientos de la caja de cambios.", "TECNICO", "sonometria_diferencial_pedal_suelto_vs_pisado", "silencio_48dba_pedal_suelto|chillido_82dba_al_pisar|frecuencia_3_4khz|vibracion_suela", "rodajes_eje_primario", "", "NO", "SI", "Rodajes de transmision manual o eje primario gastados", "L3 sonometría diferencial: 48 dBA suelto vs 82 dBA pisado confirma collarín vs primario.")
    agregar("G40-L3-02", CLASE_40, "L3", "Vehículo presenta fallo de desacoplamiento tras chirrido intenso de dos semanas de evolución. Al desmontar la caja se constató que el cojinete de empuje de embrague se gripó totalmente por desintegración de la jaula de retención de poliamida; al no girar libremente el collarín friccionó de forma continua contra las lengüetas del diafragma de la prensa hasta desgastarlas y cortar 4 dedos de acero, dejando el pedal con carrera muerta y trabando la marcha atrás.", "TALLER", "desarme_campana_dedos_cortados", "cojinete_gripado_jaula_poliamida|friccion_continua_corta_4_dedos_prensa|reversa_trabada", "disco_desgastado", "", "NO", "SI", "Disco de embrague desgastado o patinando", "L3 collarín gripado corta 4 dedos del diafragma de prensa.")
    agregar("G40-L3-03", CLASE_40, "L3", "Inspección de actuador concéntrico de desembrague hidráulico (CSC) en Ford Focus: goteo de fluido DOT 4 por la junta inferior de la campana con pérdida de nivel en el reservorio. Además de la fuga hidráulica, el rodamiento de contacto angular integrado en la cabeza del CSC presenta juego axial de 1.8 mm y juego radial de 1.2 mm; al girar la pista con la mano se aprecian asperezas rugosas y retención mecánica por falta de grasa.", "TECNICO", "metrologia_csc_holgura_y_fuga", "csc_gotea_dot4|juego_axial_1_8mm_radial_1_2mm|aspereza_manual_rodamiento", "falla_bomba_maestra", "", "NO", "SI", "Falla en bombin o bomba hidraulica de embrague", "L3 crapodina CSC con fuga de fluido y holgura axial de 1.8 mm.")
    agregar("G40-L3-04", CLASE_40, "L3", "Conductor refiere sonido de amoladora metálica exclusivamente al pisar el pedal de embrague para realizar cambios de marcha en carretera. En prueba con estetoscopio de taller se comprobó que la campana de caja amplifica el sonido en la zona frontal donde apoya la horquilla sobre el collarín. Se desmontó el conjunto verificándose que la guía tubular deslizante de acero sobre la cual corre el collarín carecía de grasa de bisulfuro de molibdeno, sufriendo rozamiento seco con microsoldaduras que rayaron la guía con surcos de 0.5 mm.", "TALLER", "inspeccion_guia_deslizante_bisulfuro", "ruido_amoladora_al_pisar|guia_tubular_sin_grasa_moly|surcos_0_5mm|microsoldaduras", "falla_disco_patina", "", "NO", "SI", "Disco de embrague desgastado o patinando", "L3 guía tubular con surcos de 0.5 mm por falta de grasa de molibdeno.")
    agregar("G40-L3-05", CLASE_40, "L3", "Hola maestro, tengo un Suzuki Swift. Cuando el auto está en neutro sin tocar nada el motor suena parejito y silencioso, pero apenas piso el pedal del embrague para meter primera suena un silbido horrible como si un rodaje estuviera triturándose. Si saco el pie del pedal el ruido se corta en seco.", "WHATSAPP", "diagnostico_swift_neutro_vs_pisado", "silencioso_en_neutro|silbido_horrible_al_pisar|se_corta_en_seco_al_soltar", "rodaje_primario", "", "NO", "SI", "Rodajes de transmision manual o eje primario gastados", "L3 relato WhatsApp de silbido al pisar que corta al soltar descartando caja.")
    agregar("G40-L3-06", CLASE_40, "L3", "Análisis con cámara termográfica infrarroja tras 15 minutos de maniobras de estacionamiento continuo con embrague acoplado y desacoplado: el cojinete de empuje registra 165°C de temperatura concentrada en el anillo interior de contacto (temperatura ambiente de campana 55°C). La grasa sintética de litio de alta temperatura se licuó y fugó por el retén de caucho NBR, dejando las 14 bolas de acero trabajando en seco.", "TECNICO", "termografia_cojinete_165c", "termografia_cojinete_165c_vs_55c|grasa_litio_licuada_fugada|14_bolas_en_seco", "falla_disco_embrague", "", "NO", "SI", "Disco de embrague desgastado o patinando", "L3 termografía registra 165°C en collarín con pérdida total de grasa.")
    agregar("G40-L3-07", CLASE_40, "L3", "Evaluación vibratoria de pedalier de embrague con acelerómetro piezoeléctrico: en reposo se registra aceleración RMS de 0.2 m/s2; al pisar el pedal a fondo la aceleración se multiplica a 4.8 m/s2 a frecuencia de 125 Hz correspondiente al paso de bolas del collarín de desembrague picado. El disco de embrague tiene 7.5 mm de espesor y el volante bimasa no presenta juego angular anómalo.", "TECNICO", "analisis_acelerometro_pedalier_4_8ms2", "aceleracion_pedal_4_8ms2_vs_0_2ms2|frecuencia_125hz_paso_bolas|disco_7_5mm_ok", "falla_bimasa", "", "NO", "NO", "", "L3 acelerómetro registra pico de 4.8 m/s2 a 125 Hz en pedal al desembragar.")
    agregar("G40-L3-08", CLASE_40, "L3", "Mi carro ase un chillido estridente como pito de tren cuando meto el pie al embrague para pasar de cambio en la pista. Si suelto el pedal el carro anda calladito sin ningun ruido. El mecanico le bajo la caja y la crapodina taba agarrada y las bolitas no giraban con la mano.", "ERROR_ORTOGRAFICO", "desarme_crapodina_agarrada", "chillido_pito_tren_al_pisar|calladito_al_soltar|crapodina_agarrada_no_gira", "falla_caja_cambios", "", "NO", "SI", "Rodajes de transmision manual o eje primario gastados", "L3 crapodina agarrada con silencio al soltar con ortografía informal.")
    agregar("G40-L3-09", CLASE_40, "L3", "Falla de concentricidad en el montaje del collarín de empuje tras sustitución de embrague: la horquilla de mando fue instalada con deformación plástica de 3.5 mm en el brazo derecho, provocando empuje asimétrico del cojinete sobre el diafragma de la prensa. Esto genera desgaste oblicuo de la pista de rozamiento con salto lateral de 0.35 mm y ruido vibratorio oscilante al presionar el pedal.", "TALLER", "montaje_asimetrico_horquilla_deformada", "horquilla_deformada_3_5mm|empuje_asimetrico_collarin|salto_0_35mm_ruido", "falla_prensa", "", "NO", "NO", "", "L3 horquilla torcida deforma empuje de collarín con salto de 0.35 mm.")
    agregar("G40-L3-10", CLASE_40, "L3", "Buenas tardes, en mi Renault Duster se siente una vibración áspera en el pedal cada vez que piso el embrague para cambiar de marcha y suena un grillo agudo. El disco no patina nada en subida y los cambios entran suaves, solo es ese chillido desagradable que se prende únicamente mientras mantengo el pedal pisado.", "WHATSAPP", "diagnostico_duster_pedal_pisado", "vibracion_aspera_pedal_al_pisar|grillo_agudo_mientras_pisa|disco_no_patina", "disco_patina", "", "NO", "SI", "Disco de embrague desgastado o patinando", "L3 grillo exclusivo bajo presión sin patinamiento de disco.")
    agregar("G40-L3-11", CLASE_40, "L3", "Desmontaje de conjunto de embrague de vehículo utilitario: el collarín de desembrague presenta holgura angular de 8 grados y marcas de fricción circular por contacto descentrado sobre los dedos de la prensa. La pista interior de acero templado tiene decoloración violeta por temperatura y el labio del guardapolvo de caucho está calcinado.", "TECNICO", "metrologia_collarin_holgura_8_grados", "holgura_angular_8_grados|decoloracion_violeta_collarin|guardapolvo_calcinado", "falla_eje_primario", "", "NO", "SI", "Rodajes de transmision manual o eje primario gastados", "L3 holgura de 8° y pista violeta calcinada en collarín.")
    agregar("G40-L3-12", CLASE_40, "L3", "Ensayo en banco de pruebas acústico: al aplicar 350 N de carga axial sobre el collarín girando a 2500 rpm el nivel de presión sonora alcanza 88 dBA con espectro armónico centrado en 4.2 kHz; al retirar la carga axial a 0 N girando a las mismas revoluciones el nivel sonoro decae instantáneamente a 42 dBA (ruido de fondo normal).", "TECNICO", "banco_acustico_carga_350n_vs_0n", "ruido_88dba_a_350n_carga|decae_a_42dba_sin_carga|armonicos_4_2khz", "falla_rodaje_caja", "", "NO", "SI", "Rodajes de transmision manual o eje primario gastados", "L3 banco acústico confirma 88 dBA con 350 N de carga vs 42 dBA sin carga.")
    agregar("G40-L3-13", CLASE_40, "L3", "El cliente reclama que el embrague suena como si raspara metal con metal únicamente al estacionar o meter reversa con el pedal a fondo. Se inspeccionó el cojinete comprobándose que el sello metálico de protección se soltó de su encastre y quedó rozando contra la carcasa del volante de inercia al avanzar el actuador hidráulico.", "TALLER", "sello_metalico_suelto_roza_volante", "sello_collarin_suelto_roza_volante|raspado_pedal_a_fondo|estacionamiento", "falla_disco_friccion", "", "NO", "SI", "Disco de embrague desgastado o patinando", "L3 sello metálico de collarín rozando contra volante al pisar a fondo.")
    agregar("G40-L3-14", CLASE_40, "L3", "Rotura catastrófica de collarín de desembrague: tras 300 km de advertencia acústica desatendida el cojinete se trabó en seco soldándose a la pista del diafragma, provocando que los dedos de la prensa se cortaran en bloque y el pedal se fuera hasta el fondo sin retorno ni posibilidad de desacople.", "TALLER", "rotura_catastrofica_collarin_soldado", "collarin_soldado_a_diafragma|dedos_prensa_cortados_en_bloque|pedal_al_fondo", "falla_bombin_embrague", "", "NO", "SI", "Falla en bombin o bomba hidraulica de embrague", "L3 gripado total de collarín destruye diafragma y vacía pedal.")
    agregar("G40-L3-15", CLASE_40, "L3", "Medición de concentricidad y rugosidad en pista de empuje de crapodina: rugosidad Ra de 3.8 micrómetros (especificación Ra menor a 0.4 um) por arrastre y microgripado repetido; la rotación manual del rodamiento presenta saltos duros cada 30 grados provocando trepidación en el pedalier de desembrague.", "TECNICO", "metrologia_rugosidad_ra_3_8um", "rugosidad_ra_3_8um_vs_0_4um|saltos_duros_cada_30_grados|trepidacion_pedal", "falla_disco_embrague", "", "NO", "SI", "Disco de embrague desgastado o patinando", "L3 rugosidad Ra de 3.8 um y saltos mecánicos en rotación de crapodina.")

    # =========================================================================
