    # --- L1 (10 casos) ---
    agregar("G41-L1-01", CLASE_41, "L1", "La caja zumba feo en neutro y el ruido se apaga cuando piso el embrague.", "COTIDIANO", "ralenti_neutro", "zumba_en_neutro_apaga_al_pisar_embrague", "", "", "SI", "NO", "", "L1 patrón canónico de rodamiento de eje primario.")
    agregar("G41-L1-02", CLASE_41, "L1", "Hola, con el carro parado suena como una licuadora que se calla al apretar el embrague.", "WHATSAPP", "ralenti_parado", "sonido_licuadora_se_calla_al_embragar", "", "", "SI", "NO", "", "L1 ruido en neutro que desaparece al desembragar.")
    agregar("G41-L1-03", CLASE_41, "L1", "Se escucha un ronquido sordo en la transmisión con el pedal de embrague suelto.", "COTIDIANO", "pedal_suelto_neutro", "ronquido_sordo_pedal_suelto", "", "", "SI", "NO", "", "L1 rugido constante en vacío.")
    agregar("G41-L1-04", CLASE_41, "L1", "Al pisar el embrague hasta el fondo el motor queda serenito sin ningún ruido.", "TALLER", "desembrague_completo", "silencio_al_pisar_embrague_a_fondo", "", "", "SI", "NO", "", "L1 cese de ruido al detener eje primario.")
    agregar("G41-L1-05", CLASE_41, "L1", "Desgaste y picadura en pistas de rodamiento delantero del eje primario de entrada.", "TECNICO", "diagnostico", "desgaste_rodamiento_eje_primario", "", "", "SI", "NO", "", "L1 reporte técnico de rodaje de directa.")
    agregar("G41-L1-06", CLASE_41, "L1", "Suena como un engranaje seco en neutro que se quita apenas piso el cloch.", "COTIDIANO", "ralenti", "engranaje_seco_neutro_quita_al_pisar_cloch", "", "", "SI", "NO", "", "L1 ruido de primario en ralentí.")
    agregar("G41-L1-07", CLASE_41, "L1", "En primera y segunda marcha zumba al compás de las revoluciones del motor.", "TALLER", "marchas_cortas", "zumbido_con_rpm_primera_segunda", "", "", "SI", "NO", "", "L1 zumbido proporcional a RPM en marchas bajas.")
    agregar("G41-L1-08", CLASE_41, "L1", "Mi caja ase un cascabeleo en neutro que cuando piso el embrague se le pasa todito.", "ERROR_ORTOGRAFICO", "neutro", "cascabeleo_neutro_se_pasa_al_pisar", "", "", "SI", "NO", "", "L1 cascabeleo en neutro con ortografía informal.")
    agregar("G41-L1-09", CLASE_41, "L1", "Buenas, al soltar el embrague en neutro empieza a sonar un traqueteo en la caja.", "WHATSAPP", "suelta_embrague_neutro", "traqueteo_al_soltar_embrague_neutro", "", "", "SI", "NO", "", "L1 traqueteo al girar eje de entrada.")
    agregar("G41-L1-10", CLASE_41, "L1", "Holgura radial excesiva en apoyo de rodamiento de bolas del árbol primario.", "TECNICO", "inspeccion", "holgura_radial_arbol_primario", "", "", "SI", "NO", "", "L1 reporte técnico de juego radial en directa.")

    # --- L2 (15 casos) ---
    agregar("G41-L2-01", CLASE_41, "L2", "Con el vehículo detenido en ralentí y la palanca en neutro se escucha un zumbido sordo en la transmisión; al pisar el pedal de embrague hasta el fondo el zumbido desaparece por completo tras 1 segundo.", "COTIDIANO", "parado_neutro_vs_embrague_pisado", "zumbido_en_neutro|desaparece_al_pisar_embrague", "falla_collarin", "", "NO", "SI", "Desgaste en collarin de empuje o crapodina de embrague", "L2 zumbido en neutro que desaparece al pisar descarta collarín.")
    agregar("G41-L2-02", CLASE_41, "L2", "Ruido de rodamiento picado en la caja de cambios que varía con las RPM del motor al acelerar en punto muerto con el embrague acoplado; al desembragar se hace el silencio.", "TALLER", "aceleracion_neutro_embragado", "ruido_varia_con_rpm_en_neutro|silencio_al_desembragar", "rodajes_diferencial", "", "NO", "SI", "Rodajes de caja mecanica o diferencial gastados", "L2 ruido con auto detenido descarta diferencial.")
    agregar("G41-L2-03", CLASE_41, "L2", "El rodamiento delantero del eje primario tiene juego radial de 0.8 mm; provoca desalineación del disco de embrague y dificultad ocasional para engranar primera.", "TECNICO", "inspeccion_juego_primario", "juego_radial_0_8mm_primario|desalineacion_disco", "falla_disco_patina", "", "NO", "SI", "Disco de embrague desgastado o patinando", "L2 juego radial en primario desalinea embrague.")
    agregar("G41-L2-04", CLASE_41, "L2", "Hola, en carretera zumba en 1ra, 2da, 3ra y 5ta pero en 4ta marcha (directa) el ruido baja muchísimo casi a nada; me dijeron que es el eje primario de la caja.", "WHATSAPP", "comparativa_marchas_cuarta_directa", "zumba_1_2_3_5|silencio_en_cuarta_directa", "rodajes_diferencial", "", "NO", "SI", "Rodajes de caja mecanica o diferencial gastados", "L2 silenciamiento en 4ta directa confirma eje primario vs diferencial.")
    agregar("G41-L2-05", CLASE_41, "L2", "Al drenar el aceite de la transmisión se encuentra limalla plateada fina en el imán; el rodamiento posterior del árbol primario presenta picaduras en la pista exterior.", "TECNICO", "drenaje_valvulina_pitting_primario", "limalla_plateada_iman|pitting_pista_exterior_primario", "falta_aceite_caja", "", "NO", "SI", "Falta o degradacion de aceite de caja de cambios", "L2 limalla de rodamiento con lubricante a nivel.")
    agregar("G41-L2-06", CLASE_41, "L2", "Ronroneo continuo en la parte delantera que se escucha al estar estacionado esperando pasajeros; al apoyar el pie y hundir el embrague se corta instantáneamente.", "COTIDIANO", "estacionado_pasajeros_ralenti", "ronroneo_estacionado_ralenti|corta_al_hundir_embrague", "ruido_motor_bielas", "", "NO", "NO", "", "L2 ronroneo en reposo que corta al desembragar descarta motor.")
    agregar("G41-L2-07", CLASE_41, "L2", "Rodamiento central del eje intermediario de la transmisión manual con jaula de bolas rota; produce cascabeleo metálico al soltar el embrague en neutro.", "TALLER", "inspeccion_desarme_caja", "jaula_bolas_rota_intermediario|cascabeleo_embrague_suelto", "falla_collarin", "", "NO", "SI", "Desgaste en collarin de empuje o crapodina de embrague", "L2 cascabeleo con pedal suelto descarta collarín.")
    agregar("G41-L2-08", CLASE_41, "L2", "Mi carro ase un zumbido en neutro como si algo raspase adentro de la caja y cuando meto el cloch a fondo se le kita todo el ruido.", "ERROR_ORTOGRAFICO", "neutro_vs_cloch", "zumbido_en_neutro|se_quita_al_meter_cloch", "falla_crapodina", "", "NO", "SI", "Desgaste en collarin de empuje o crapodina de embrague", "L2 zumbido en neutro que quita al meter cloch con ortografía informal.")
    agregar("G41-L2-09", CLASE_41, "L2", "Buenas maestro, en el semáforo suena un cloc-cloc suave en la caja que desaparece apenas piso el embrague para meter primera; el disco no patina para nada.", "WHATSAPP", "semaforo_ralenti", "cloc_cloc_suave_caja|desaparece_al_pisar_embrague|no_patina", "disco_desgastado", "", "NO", "SI", "Disco de embrague desgastado o patinando", "L2 golpeteo en neutro sin patinamiento de disco.")
    agregar("G41-L2-10", CLASE_41, "L2", "Holgura axial del eje primario de 0.65 mm medida con comparador; provoca que el retén frontal del eje gotee aceite hacia la campana de embrague.", "TECNICO", "medicion_holgura_axial_primario", "holgura_axial_0_65mm_primario|fuga_reten_frontal", "falla_bomba_embrague", "", "NO", "SI", "Falla en bombin o bomba hidraulica de embrague", "L2 juego axial de primario daña retén frontal de caja.")
    agregar("G41-L2-11", CLASE_41, "L2", "Al rodar en neutro a 60 km/h por inercia el zumbido desaparece si el motor está en ralentí y el pedal de embrague pisado; descarta rodamiento de maza de rueda.", "COTIDIANO", "rodada_inercia_60kmh", "desaparece_al_pisar_embrague_a_60kmh", "rodamiento_rueda", "", "NO", "SI", "Rodamiento de maza o rodaje de rueda picado (zumbido de rodadura)", "L2 silencio a 60 km/h al pisar embrague descarta maza de rueda.")
    agregar("G41-L2-12", CLASE_41, "L2", "Casquillo de agujas de apoyo de la punta del eje primario en el cigüeñal (rodaje de guía piloto) engranado en seco; produce chirrido agudo al desacoplar.", "TECNICO", "inspeccion_rodaje_piloto", "rodaje_piloto_ciguenal_seco|chirrido_al_desacoplar", "falla_collarin", "", "NO", "SI", "Desgaste en collarin de empuje o crapodina de embrague", "L2 rodamiento piloto de cigüeñal vs collarín de empuje.")
    agregar("G41-L2-13", CLASE_41, "L2", "Zumbido que aumenta al acelerar en 1ra, 2da y 3ra marcha y se apaga en neutro pisando el embrague; el nivel de aceite de la caja de cambios está al máximo.", "TALLER", "aceleracion_marchas_bajas", "zumbido_1_2_3_aumenta_con_rpm|apaga_al_pisar|aceite_al_maximo", "falta_aceite_caja", "", "NO", "SI", "Falta o degradacion de aceite de caja de cambios", "L2 zumbido dependiente de RPM con aceite lleno.")
    agregar("G41-L2-14", CLASE_41, "L2", "Pistas de rodadura del rodamiento de entrada con picado severo por contaminación con agua vieja; zumbido de frecuencia constante en neutro.", "TECNICO", "desarme_rodamiento_entrada", "picado_severo_pistas_agua|zumbido_frecuencia_constante_neutro", "falla_diferencial", "", "NO", "SI", "Rodajes de caja mecanica o diferencial gastados", "L2 picado en pista de entrada con zumbido en neutro vs diferencial.")
    agregar("G41-L2-15", CLASE_41, "L2", "Ruido de rozamiento metálico que inicia suave al arrancar el motor y se incrementa al acelerar en vacío; pisando el embrague a fondo se silencia por completo.", "COTIDIANO", "aceleracion_vacio_estacionado", "ruido_rozamiento_acelerar_vacio|silencio_al_pisar_fondo", "falla_motor_bielas", "", "NO", "NO", "", "L2 prueba en vacío: acelerar en neutro zumba, desembragar silencia.")

    # --- L3 (15 casos) ---
    agregar("G41-L3-01", CLASE_41, "L3", "En un Toyota Yaris con transmisión manual de 5 velocidades se manifiesta un ruido áspero de rodadura en neutro con el motor encendido a 750 rpm de ralentí. Al aplicar el pedal de embrague hasta el fondo, tras 1.2 segundos el eje primario se detiene por inercia y el ruido desaparece al 100% dejando el motor en silencio total. Al soltar nuevamente el pedal en neutro el ruido reaparece de inmediato. Con estetoscopio colocado en la carcasa frontal de la caja junto a la campana se miden 76 dB en neutro que caen a 44 dB al desembragar. Se desmontó la caja encontrándose el rodamiento de bolas del eje primario (referencia 6205) con la pista de rodadura picada con desprendimiento de material de 3 mm.", "TECNICO", "estetoscopio_76db_neutro_vs_44db_pisado", "76db_en_neutro_cae_a_44db_al_pisar_embrague|eje_primario_se_detiene_silencio|rodamiento_6205_picado", "falla_collarin_empuje", "", "NO", "SI", "Desgaste en collarin de empuje o crapodina de embrague", "L3 estetoscopio: 76 dB en neutro cae a 44 dB al pisar confirmando eje primario vs collarín.")
    agregar("G41-L3-02", CLASE_41, "L3", "Conductor reporta zumbido en la transmisión que acompaña a las revoluciones del motor en 1ra, 2da, 3ra y 5ta marcha, pero que disminuye drásticamente en 4ta velocidad (marcha directa 1:1 donde el tren secundario no transmite par). Con el auto detenido y la palanca en neutro, el zumbido se escucha claramente con el embrague suelto y desaparece al pisar el pedal. Se midió el juego radial del eje primario con reloj comparador registrándose 0.62 mm de holgura (tolerancia máxima 0.05 mm) por fatiga de bolas en el rodamiento frontal.", "TALLER", "prueba_cuarta_directa_vs_otras", "zumbido_1_2_3_5_cae_en_cuarta_directa|juego_radial_primario_0_62mm|silencio_al_pisar_en_neutro", "rodajes_diferencial", "", "NO", "SI", "Rodajes de caja mecanica o diferencial gastados", "L3 silenciamiento en 4ta directa y juego de 0.62 mm en primario descarta diferencial.")
    agregar("G41-L3-03", CLASE_41, "L3", "Análisis con analizador de vibraciones FFT en ralentí con vehículo estacionado: con embrague acoplado en neutro se registra pico dominante de 38 mm/s a frecuencia de 12.5 Hz (coincidente exactamente con 1x velocidad de rotación del motor a 750 rpm) y armónicos en 112 Hz (frecuencia cinemática BPFI de pista interior del rodamiento de directa). Al pisar el pedal de embrague ambos picos colapsan instantáneamente a nivel de ruido base de 1.8 mm/s. El collarín de empuje fue inspeccionado encontrándose nuevo y sin holguras.", "TECNICO", "analisis_fft_bpfi_112hz_primario", "pico_fft_112hz_bpfi_primario|colapsa_al_pisar_embrague|collarin_nuevo_ok", "desgaste_collarin", "", "NO", "SI", "Desgaste en collarin de empuje o crapodina de embrague", "L3 análisis FFT confirma frecuencia BPFI de 112 Hz del rodamiento primario.")
    agregar("G41-L3-04", CLASE_41, "L3", "Vehículo presenta rumorosidad áspera al rodar que muchos atribuyeron a rodamientos de maza de rueda. En prueba de carretera a 80 km/h se colocó la palanca en neutro y se pisó el pedal de embrague manteniendo el auto rodando por inercia: el ruido desapareció al 100% a pesar de que las ruedas giraban a 80 km/h (descartando de forma absoluta rodamientos de rueda y diferencial). Al soltar el embrague con el motor en marcha a 80 km/h el zumbido regresó de inmediato confirmando avería en el tren de engranajes del primario.", "TALLER", "prueba_inercia_80kmh_descarta_ruedas", "silencio_a_80kmh_inercia_pedal_pisado|ruido_vuelve_al_soltar|descarta_ruedas_diferencial", "rodamiento_rueda", "", "NO", "SI", "Rodamiento de maza o rodaje de rueda picado (zumbido de rodadura)", "L3 prueba de inercia a 80 km/h con embrague pisado descarta ruedas y diferencial.")
    agregar("G41-L3-05", CLASE_41, "L3", "Hola maestro, tengo un Nissan Tiida mecánico. Cuando estoy parado en el semáforo con el carro en neutro suena un traqueteo feo como si tuviera piedritas adentro de la caja. Apenas piso el embrague para meter primera el ruido desaparece por completo como por arte de magia. El embrague no patina y corta bien.", "WHATSAPP", "diagnostico_tiida_traqueteo_neutro", "traqueteo_neutro_como_piedritas|desaparece_al_pisar_embrague|no_patina", "disco_desgastado", "", "NO", "SI", "Disco de embrague desgastado o patinando", "L3 relato WhatsApp de traqueteo en neutro que desaparece al pisar embrague.")
    agregar("G41-L3-06", CLASE_41, "L3", "Desmontaje de transmisión manual de 5 velocidades: el rodamiento de bolas blindado de entrada del eje primario tiene la pista exterior suelta girando sobre el propio alojamiento de aluminio de la carcasa, habiendo desgastado el asiento en 0.45 mm. El retén frontal de aceite sufrió deformación por la excentricidad del eje permitiendo que 300 ml de valvulina fugaran hacia la campana sin llegar a empapar el disco.", "TECNICO", "inspeccion_alojamiento_carcasa_desgastado_0_45mm", "pista_exterior_gira_en_carcasa|alojamiento_desgastado_0_45mm|excentricidad_eje_primario", "falta_aceite_caja", "", "NO", "SI", "Falta o degradacion de aceite de caja de cambios", "L3 pista exterior gira en carcasa desgastando alojamiento 0.45 mm.")
    agregar("G41-L3-07", CLASE_41, "L3", "Inspección de rodamiento guía piloto de agujas montado en el extremo posterior del cigüeñal: los rodillos de agujas se destruyeron por falta de lubricación quedando el muñón del primario apoyando metal con metal. A diferencia del rodamiento de caja que suena en neutro con pedal suelto, este rodaje piloto emite un chillido agudo exclusivamente cuando se pisa el embrague a fondo con marcha puesta y motor girando.", "TALLER", "diagnostico_rodamiento_piloto_ciguenal", "rodamiento_piloto_agujas_destruido|chillido_al_desembragar_con_marcha|primario_sano", "collarin_embrague", "", "NO", "SI", "Desgaste en collarin de empuje o crapodina de embrague", "L3 rodamiento piloto de agujas destruido en cigüeñal vs rodaje de primario.")
    agregar("G41-L3-08", CLASE_41, "L3", "Mi carro ase una tembladera y zumbido en neutro cuando esta prendido parado en la vereda. Si le piso el pedal del cloch se caya todito y no suena nada. El mecanico le desarmo la caja y el rodaje grande de la directa taba con las bolas comidas y sueltas.", "ERROR_ORTOGRAFICO", "desarme_rodaje_directa", "zumbido_en_neutro_parado|se_calla_al_pisar_cloch|rodaje_directa_bolas_comidas", "crapodina", "", "NO", "SI", "Desgaste en collarin de empuje o crapodina de embrague", "L3 rodaje de directa con bolas comidas con ortografía informal.")
    agregar("G41-L3-09", CLASE_41, "L3", "Comprobación con estetoscopio de taller en 4 puntos de la transmisión con motor en marcha a 800 rpm: punto 1 (carcasa de diferencial) registra 35 dB; punto 2 (tapa trasera de 5ta) registra 38 dB; punto 3 (campana frontal junto a retén de directa) registra 79 dB; al accionar el pedal de embrague el punto 3 cae inmediatamente a 34 dB confirmando origen en rodamiento delantero de primario.", "TECNICO", "estetoscopio_4_puntos_79db_vs_35db", "punto_campana_79db_cae_a_34db|diferencial_35db_silencioso|rodamiento_directa_danado", "rodajes_diferencial", "", "NO", "SI", "Rodajes de caja mecanica o diferencial gastados", "L3 estetoscopio en 4 puntos aísla ruido en directa (79 dB) y descarta diferencial.")
    agregar("G41-L3-10", CLASE_41, "L3", "Buenas tardes maestro, tengo un Gol 1.6. Cuando el carro está prendido en neutro suena un siseo constante shhh-shhh en el motor que parece de faja. Le sacamos las fajas de accesorios y seguía sonando igualito; pero al pisar el embrague el siseo se apaga al segundo exacto. Los cambios entran perfectos y no rascan.", "WHATSAPP", "diagnostico_gol_siseo_neutro", "siseo_constante_neutro|persiste_sin_fajas_accesorios|apaga_al_pisar_embrague", "falla_faja_distribucion", "", "NO", "SI", "Desgaste en collarin de empuje o crapodina de embrague", "L3 siseo en neutro descartado de accesorios que apaga al pisar embrague.")
    agregar("G41-L3-11", CLASE_41, "L3", "Desgaste por fatiga de contacto con desprendimiento laminar en pista interior de rodamiento de contacto angular del eje secundario/primario: holgura axial resultante de 0.55 mm provoca que al acelerar en 2da y 3ra marcha los engranajes helicoidales sufran empuje axial descentrado provocando zumbido de engrane proporcional al torque.", "TECNICO", "desprendimiento_laminar_holgura_0_55mm", "desprendimiento_laminar_pista|holgura_0_55mm|zumbido_engrane_segunda_tercera", "falta_aceite_caja", "", "NO", "SI", "Falta o degradacion de aceite de caja de cambios", "L3 holgura axial de 0.55 mm por desprendimiento laminar en pista interior.")
    agregar("G41-L3-12", CLASE_41, "L3", "Prueba de calado acústico en taller: con vehículo detenido y motor a 2000 rpm en neutro el nivel sonoro en habitáculo es de 68 dBA con pedal suelto; al desembragar cae a 52 dBA. Al realizar la prueba en marcha rodando a 50 km/h en neutro el ruido se mantiene al embragar y se extingue al desembragar demostrando que el ruido depende del giro del primario y no de las ruedas.", "TALLER", "prueba_calado_acustico_neutro_rodando", "68dba_suelto_vs_52dba_desembragado|mismo_patron_rodando_a_50kmh|descarta_ruedas", "rodamiento_rueda", "", "NO", "SI", "Rodamiento de maza o rodaje de rueda picado (zumbido de rodadura)", "L3 calado acústico a 50 km/h demuestra dependencia exclusiva del eje primario.")
